export type ManualSection={id:string;title:string;intro?:string;steps?:string[];notes?:string[];subsections?:{title:string;items:string[]}[];links?:{href:string;label:string}[]};
export type ManualCopy={title:string;description:string;kicker:string;intro:string;updated:string;language:string;contents:string;home:string;discover:string;top:string;sections:ManualSection[]};
export const manualCopy:Record<'nl'|'en'|'fr',ManualCopy>={
 nl:{title:'Handleiding van Côte de Duras',description:'Zoeken, de gemeentegids, kerstmarkten, je vermelding beheren, adverteren, betalen en websitebeheer.',kicker:'Hulp voor bezoekers, ondernemers en beheerders',intro:'Côte de Duras brengt evenementen en lokale adressen samen. Je kunt zonder account zoeken, een uitje plannen en voorzieningen in dezelfde plaats vinden.',updated:'Bijgewerkt op 16 november 2026',language:'Kies bovenaan Nederlands, English of Français. Een nieuw bezoek begint in het Frans; je eigen taalkeuze blijft tijdens het doorklikken behouden. Namen, adressen en contactgegevens worden niet vertaald.',contents:'Waar wil je hulp bij?',home:'← Naar de homepage',discover:'Open het zoekblok →',top:'↑ Terug naar de inhoud',sections:[
 {id:'zoeken',title:'1. Begin bij Ontdek Duras en omgeving',steps:['Kies bij Jouw plaats de gemeente van waaruit je wilt zoeken.','Kies Wat is er te doen? voor evenementen, of Wat zoek je in de buurt? voor lokale adressen en voorzieningen.','Met de knoppen Alles, Evenementen, Eten & drinken, Winkelen en Praktisch wissel je van onderdeel. Je gekozen plaats blijft behouden.','Alles toont zowel de agenda als de gemeentegids. Bij Eten & drinken kun je wisselen tussen restaurants en cafés. Bij Winkelen en Praktisch staan snelkeuzes voor verschillende rubrieken.'],notes:['De afstandsinstelling van de agenda geldt voor agendaresultaten. De gemeentegids gebruikt per voorziening een passende zoekafstand; een resultaat kan buiten de gekozen gemeente liggen.'],links:[{href:'/#local-discovery',label:'Ontdek de streek →'}]},
 {id:'agenda',title:'2. Evenementen zoeken en datums kiezen',steps:['Kies Evenementen en stel een afstand van 10, 25 of 50 kilometer in. De agenda begint op 10 kilometer.','Kies Vandaag, Deze week of Dit weekend. Deze week loopt van maandag tot en met zondag; Dit weekend betekent zaterdag en zondag. Op zondag blijft het lopende weekend geselecteerd. De datums volgen de Franse lokale tijd.','Een ingevulde datum zoekt op die dag. Vul een begin- en einddatum in voor een periode; beide dagen tellen mee. Meerdaagse evenementen tellen mee wanneer ze de gekozen periode overlappen.','Met Alle datums of Datums wissen verwijder je het datumfilter. Zonder datumfilter zie je ook vaste adressen; met een datumfilter alleen evenementen met een datum.','Verfijn met Soort activiteit of Alleen gratis activiteiten. Gebruik Toon meer activiteiten om extra resultaten te bekijken.'],notes:['Gebruik mijn locatie vraagt toestemming aan je browser. Als je locatie buiten de streek valt of onbruikbaar is, kan de site terugvallen op de gekozen gemeente; daarover verschijnt een melding.','Open een evenement via de foto, titel of detailknop. Controleer datum, locatie en prijs. Reserveren en Website organisator openen de website van de aanbieder; een klik is nog geen boeking.','Bij Maak er een gezellig dagje van kun je vanuit de evenementdetails naar eten, winkels of praktische voorzieningen in dezelfde plaats. Die keuze verschijnt als de plaats aan een gemeente kan worden gekoppeld.','Geen resultaat? Vergroot de afstand, wis de datums, kies Alle soorten of zet het filter voor gratis activiteiten uit. Controleer voor vertrek de informatie bij de organisator.'],links:[{href:'/#agenda',label:'Open de agenda →'}]},
 {id:'kerstmarkten',title:'3. Kerstmarkten rond Duras',steps:['Open de kerstmarktenpagina via het blok op de homepage.','De resultaten beginnen bij de kerstmarkten het dichtst bij Duras en lopen op in afstand, tot 50 kilometer. Bij gelijke afstand staat de vroegste datum eerst.','Kies een dag, periode of plaats om de selectie te verfijnen. De afstand blijft gemeten vanaf Duras, ook als je op een andere plaats filtert.','Gebruik de pijlen in de carrousel om een andere markt te bekijken. Je kunt de automatische wisseling pauzeren. Open een kaart voor de details.','Met Deel deze selectie deel je de pagina inclusief je gekozen plaats en datums. Op geschikte apparaten opent het deelmenu; anders wordt de link gekopieerd.'],notes:['De carrousel gebruikt dezelfde selectie als de resultaten. Bij een lege selectie kun je Alle datums kiezen of de plaatskeuze wissen.'],links:[{href:'/marches-de-noel',label:'Bekijk de kerstmarkten →'}]},
 {id:'gemeentegids',title:'4. Winkels en praktische voorzieningen',steps:['Kies Winkelen of Praktisch in het gezamenlijke zoekblok, of open Gemeente informatie in het menu.','De gids haalt de gekozen rubriek voor je plaats op. Gebruik een snelkeuze of kies een andere rubriek bij Welke informatie zoek je?. Met Toon informatie kun je de gegevens opnieuw ophalen.','Kies Alle categorieën — complete gemeentegids voor het hele lokale overzicht. Gebruik de getoonde telefoon-, e-mail-, website- en kaartlinks voor contact of een route.'],notes:['Rubrieken omvatten onder meer winkels, gemeentehuis, medische voorzieningen, parkeren, laadpunten en openbaar vervoer. Noodnummers is een informatierubriek, geen bedrijvenlijst.','Openingstijden en foto’s zijn alleen beschikbaar wanneer een bron die gegevens levert. Foto nog niet beschikbaar betekent dat er geen geschikte bevestigde foto is; de contactgegevens blijven bruikbaar.','Let op de werkelijke plaats en afstand. Een ontbrekende vermelding bewijst niet dat een voorziening niet bestaat. De kaarten bij parkeren bevestigen geen actuele beschikbaarheid van parkeerplaatsen.'],links:[{href:'/#gemeenten',label:'Open de gemeentegids →'}]},
 {id:'toevoegen',title:'5. Een evenement of bedrijf aanmelden',steps:['Zoek eerst of de vermelding al bestaat. Voor wijzigen of adverteren hoef je geen tweede vermelding aan te maken.','Open Vermelding toevoegen / beheren. Kies een evenement of activiteit, een vaste vermelding, of een winkel of dienst in de gemeentegids.','Vul titel of bedrijfsnaam, categorie, plaats, adres en beschrijving in. Alleen een evenement heeft een begin- en eventueel einddatum met tijd nodig. Vul de gevraagde website-, reserverings- en bronlinks in.','Voeg desgewenst een eigen of toegestane JPG-, PNG- of WebP-foto van maximaal 5 MB toe. Een bestand kiezen is nog niet opslaan.','Kies Gratis vermelding of een betaalde advertentie. Controleer de voorbeeldweergave en alle verplichte velden en sla de inzending op.','Bewaar de persoonlijke beheerlink die verschijnt: kopieer de link of bewaar hem als bestand. Gebruik ook het gevraagde privé-e-mailadres voor de beheerlink. De inzending wacht eerst op controle.'],notes:['Gratis vermelding betekent geen advertentiekosten. Dit evenement is gratis gaat over de toegangsprijs voor bezoekers. Dat zijn twee verschillende keuzes.','Na goedkeuring kan een bevestigingsmail met de beheerlink worden verzonden. Bewaar de link als een wachtwoord; deel hem niet op sociale media.'],links:[{href:'/mijn-vermelding',label:'Vermelding toevoegen / beheren →'},{href:'/evenement/nieuw',label:'Een evenement aanmelden →'},{href:'/gemeentegids/aanmelden',label:'Een winkel of dienst aanmelden →'}]},
 {id:'wijzigen',title:'6. Gegevens, foto en beheerlink',steps:['Open je persoonlijke beheerlink, of kies Beheerlink openen in Vermelding toevoegen / beheren en plak de volledige link.','Controleer bovenaan welke vermelding je beheert. Kies Gegevens wijzigen en pas tekst, contactgegevens, datums of foto aan.','Klik op Wijzigingen opslaan en wacht op de bevestiging. Eigenaarswijzigingen worden gecontroleerd voordat ze openbaar verschijnen. Bestaande advertentieafspraken en betaalhistorie blijven bewaard.','Met Adverteren en Betalingen open je de andere onderdelen van dezelfde vermelding. Sla wijzigingen op voordat je wisselt. Met Andere vermelding openen kun je naar een andere persoonlijke beheerlink gaan.'],notes:['Bij een gidsbedrijf kun je ook het zakelijke e-mailadres en de openingstijden aanpassen. Vraag hulp als de vestigingsgemeente of bedrijfsrubriek moet veranderen.','Een opgeslagen eigen foto krijgt voorrang op een gevonden bronfoto. Als je alleen een foto kiest maar niet opslaat, is de foto nog niet gewijzigd.'],subsections:[{title:'Geen beheerlink of een fout gevonden?',items:['Zoek de vermelding via Zoeken & aanvragen en kies Beheer of correctie aanvragen. Vermeld je relatie tot de organisatie en wat er moet veranderen. De beheerder controleert je bevoegdheid voordat toegang wordt verstrekt.','Bij Beheerlink & hulp kun je ook herstel aanvragen. E-mail met herstelverzoek opstellen opent een concept in je eigen e-mailprogramma; je verstuurt dit bericht daar zelf.','Een correctiemelding verandert de openbare gegevens niet direct. Na herstel kunnen oude beheerlinks ongeldig zijn.']}],links:[{href:'/mijn-vermelding',label:'Mijn vermelding beheren →'}]},
 {id:'advertenties',title:'7. Adverteren in agenda of gemeentegids',intro:'Open je persoonlijke beheerlink en kies Adverteren. De voorbeeldkaarten laten zien waar je advertentie verschijnt; een voorbeeld of betaaloverzicht is nog geen actieve advertentie.',subsections:[{title:'Evenementenagenda',items:['Kies één of meer vormen: een omkaderde vermelding, categorieadvertentie of homepageadvertentie. Je gewone vermelding blijft bestaan.','Een categorieadvertentie hoort bij de gekozen evenementcategorie. Een homepageadvertentie verschijnt op de homepage. Een omkaderde vermelding valt op tussen de resultaten.']},{title:'Gemeentegids',items:['Een omkaderde vermelding valt op in je gemeente en rubriek. Een rubriekpartner krijgt een extra kaart bij die rubriek; een gemeentepartner bij de rubrieken van de gekozen gemeente.','De advertentieplekken van de gids staan los van de plekken in de agenda. Een advertentie maakt van een gidsbedrijf geen evenement.']}],steps:['Kies de advertentievormen, begindatum en looptijd. De actuele prijzen en het totaal staan op het scherm.','Controleer de voorbeelden en je contact- en factuurgegevens. Deze privégegevens worden niet bij je openbare vermelding getoond.','Ga via de aangegeven knop naar Mollie om de aanvraag te betalen. Plaatsing volgt na inhoudelijke goedkeuring en betaalbevestiging, binnen de gekozen periode en bij beschikbare ruimte.'],links:[{href:'/mijn-vermelding',label:'Mijn advertentiemogelijkheden bekijken →'}]},
 {id:'betalingen',title:'8. Betalingen en facturen',steps:['Open je persoonlijke beheerlink en kies Betalingen. Je ziet de aanvragen, perioden, bedragen en betaalstatussen van die vermelding.','Gebruik Betalen via Mollie of Betaling hervatten via Mollie voor een openstaande aanvraag. Controleer bij twijfel eerst de betaalstatus om dubbele betalingen te voorkomen.','Een verlopen, afgebroken of mislukte betaling kan opnieuw worden geopend wanneer die mogelijkheid bij de aanvraag staat. Maak daarvoor geen nieuwe vermelding aan.','Alleen terugkeren van Mollie is geen betaalbevestiging. Gebruik Betaalstatus opnieuw controleren als de bevestiging nog ontbreekt.'],notes:['Betaald betekent dat de betaling bevestigd is; de advertentie moet ook zijn goedgekeurd en binnen de gekozen periode vallen. Terugbetaald betekent dat de betaling is teruggestort.','De factuur staat los van het betaaloverzicht. Wanneer de beheerder een factuur opstelt, krijgt die een opvolgend nummer en wordt de PDF naar het factuur-e-mailadres verzonden. Er is momenteel geen factuurdownloadknop in het persoonlijke betaaloverzicht.','Geen factuur ontvangen? Controleer je spammap en mail de naam van je vermelding en de aanvraagreferentie naar info@cotededuras.com.'],links:[{href:'/mijn-vermelding?onderdeel=betalingen',label:'Open mijn betalingen →'}]},
 {id:'hulp',title:'9. Delen, taalkeuze en hulp',notes:['Externe websites openen in een nieuw tabblad. De beschikbaarheid en reservering worden door de aanbieder afgehandeld.','Via de sociallinks onderaan kun je Côte de Duras volgen en de website delen. Plaats je persoonlijke beheerlink nooit in een openbaar bericht.','Met Statistiekvoorkeuren onderaan verander je je keuze voor het meten van websitegebruik.','Voor een groter beeld op je telefoon of tablet kun je de website in Safari, Chrome of een andere gewone browser openen.','Mail bij een probleem de titel van de vermelding, de betreffende pagina en eventueel je aanvraagreferentie naar info@cotededuras.com.'],links:[{href:'/contact',label:'Contactgegevens →'},{href:'mailto:info@cotededuras.com',label:'Mail Côte de Duras →'}]},
 {id:'voor-beheerders',title:'10. Voor beheerders: inhoud en aanvragen',intro:'De beheerderslogin staat onderaan de website. Deze omgeving staat los van een persoonlijke beheerlink voor één vermelding.',subsections:[{title:'Evenementen en imports',items:['Open Wacht op controle voor handmatige inzendingen of Alle evenementen voor het volledige beheeroverzicht. Zoek op naam en filter op categorie.','BEWERKEN opent gegevens en foto. Controleer wijzigingen en sla op. GOEDKEUREN publiceert een gecontroleerde inzending. Inhoudelijke goedkeuring bevestigt geen betaling.','Vernieuwen haalt opgeslagen gegevens opnieuw op. Importknoppen halen brongegevens op voor een voorvertoning. Controleer titels, datums, foto’s en categorieën voordat je opslaat.','Nieuwe imports uit de daarvoor ingestelde bronnen kunnen automatisch worden goedgekeurd. Handmatige inzendingen en eigenaarswijzigingen worden afzonderlijk gecontroleerd. Lees de resultaatmelding bij een gedeeltelijke fout.','Sociale post voorvertonen gebruikt de link en tekst van een concreet bericht. Het formulier scant geen besloten groepen automatisch.']},{title:'Verwijderen en bedrijven beheren',items:['VERWIJDEREN archiveert de vermelding na bevestiging; ze verdwijnt uit de openbare en actieve lijst. Gekoppelde aanvragen en facturen blijven bewaard. Er wordt geen terugbetaling uitgevoerd.','Open Gemeentegids · Bedrijven beheren voor bedrijfsaanmeldingen, contactgegevens, openingstijden en foto’s. Beoordeel nieuwe aanmeldingen en controleer na opslaan de openbare weergave.','Het beheertotaal kan afwijken van de bezoekersteller door aanvragen die wachten op controle, verlopen evenementen en de gekozen bezoekersfilters.']},{title:'Beheeraanvragen en e-mail',items:['Controleer bij een beheeraanvraag de bevoegdheid via onafhankelijk gevonden officiële contactgegevens. Leg de controle en beslissing vast en controleer het e-mailadres voor de beheerlink.','Een correctiemelding afhandelen wijzigt de inhoud niet automatisch. Pas de gegevens eerst in het juiste beheeroverzicht aan.','Controleer bij Strato-mailverbinding de verbinding, verzendinstelling, planning en wachtrij. Een testmail of bericht dat door de mailserver is geaccepteerd, is geen bewijs van ontvangst of lezen.','De wachtrij voor aanvragen en beheerlinks en die voor facturen hebben eigen acties voor opnieuw proberen. Raadpleeg de actuele meldingen voordat je opnieuw verstuurt.','Controleer bij automatische imports en dagelijkse updates de ingestelde planning en samenvatting. Een onbereikbare bron kan een aandachtspunt opleveren.']} ]},
 {id:'facturen-beheer',title:'11. Voor beheerders: facturen en betalingen',steps:['Open Facturen & advertentieaanvragen en daarna het factuuroverzicht. Controleer echte aanvragen afzonderlijk op naam, periode, bedrag en factuurgegevens.','Controleer bij Factuurinstellingen aanpassen het btw-regime, de bedrijfsgegevens en eventuele toepasselijke vrijstellingsvermelding. Sla wijzigingen op en controleer de bevestiging.','Factuur opstellen en versturen geeft een volgend factuurnummer en zet de PDF-mail klaar. Een Mollie-betaling maakt deze factuur niet automatisch aan.','Controleer de verzendstatus. E-mails opnieuw proberen verwerkt wachtende of mislukte factuurmails zonder nieuwe facturen of nummers te maken.','Testaanvraag uit lijst verwijderen is alleen voor geregistreerde testaanvragen. Alleen TEST in een titel zetten is niet voldoende. Uitgegeven facturen en hun nummerreeks blijven bewaard.'],notes:['Totaal gefactureerd betreft uitgegeven, niet-geannuleerde facturen zonder testfacturen. Een factuurstatus is iets anders dan een Mollie-betaalstatus. Persoonlijke factuurgegevens zijn alleen voor beheer zichtbaar.']},
 {id:'rapportages-beheer',title:'12. Voor beheerders: bezoekers en marketing',steps:['Open Bezoekers & advertentiebereik en kies de periode van 7, 30, 90 of 365 dagen. Klik zo nodig op Vernieuwen.','Gebruik Marketing & herkomst voor kanalen, campagnes en de pagina waarop bezoekers binnenkwamen. De andere tabbladen tonen het overzicht, dagen en maanden, categorieën, plaatsen, zoekfilters en adverteerders.','Vergelijk bezoekers en bezoeken met geopende vermeldingen en doorklikken. Gebruik herkenbare campagnelinks om campagnes van elkaar te kunnen onderscheiden.','Bewaar het rapport via Excel opslaan als… of CSV opslaan als…. Met Volledig rapport direct bekijken lees je de gegevens ook binnen de beheermodule.'],notes:['De cijfers gaan over gemeten gebruik met toestemming. Een bezoeker is een browsercode en geen gegarandeerd unieke persoon. Beheerders worden uitgesloten.','Categorieën kunnen overlappen. Een reserveringsklik is geen bevestigde boeking en de statistieken tonen geen volledige telling van iedereen die de site gebruikt.']}
 ]},
 en:{title:'Côte de Duras user guide',description:'Find events and local services, browse Christmas markets, manage your listing, advertise and check payments.',kicker:'Help for visitors, businesses and administrators',intro:'Côte de Duras brings events and local addresses together. Search without an account, plan an outing and find useful services in the same town.',updated:'Updated 16 November 2026',language:'Choose Nederlands, English or Français at the top. A new visit starts in French; your chosen language is retained as you browse. Names, addresses and contact details are not translated.',contents:'What do you need help with?',home:'← Back to the homepage',discover:'Open the search area →',top:'↑ Back to contents',sections:[
 {id:'zoeken',title:'1. Start with Discover Duras and the surrounding area',steps:['Select the town you want to search from.','Choose What’s on? for events, or What’s nearby? for local addresses and services.','Switch between Everything, Events, Eat & drink, Shopping and Practical. Your selected town stays the same.','Everything shows both the calendar and the local guide. Under Eat & drink, switch between restaurants and cafés. Shopping and Practical offer shortcuts to their different sections.'],notes:['The calendar radius applies to calendar results. The local guide uses a suitable search distance for each service; a result may be outside your selected town.'],links:[{href:'/#local-discovery',label:'Discover the area →'}]},
 {id:'agenda',title:'2. Find events and choose dates',steps:['Choose Events and a radius of 10, 25 or 50 km. The calendar starts at 10 km.','Use Today, This week or This weekend. A week runs from Monday to Sunday; a weekend is Saturday and Sunday. On Sunday, the current weekend remains selected. Dates use local time in France.','One date searches that day. Enter start and end dates for a period, including both days. Events spanning several days are included when they overlap your selection.','All dates or Clear dates removes the date filter. Without dates, permanent addresses also appear; with dates, only dated events appear.','Refine by activity category or free admission. Use Show more activities to see additional results.'],notes:['Use my location asks your browser for permission. If your location is outside the area or unusable, the site may search around your selected town instead and show a message.','Open an event using its photo, title or details button. Check the date, location and admission. Booking and organiser links open the provider’s website; a click is not a confirmed booking.','Make a day of it links from event details to food, shops and practical services in the same town, when that town can be identified.','No suitable results? Widen the radius, clear dates, select all categories or remove the free-admission filter. Confirm current information with the organiser before travelling.'],links:[{href:'/#agenda',label:'Open the calendar →'}]},
 {id:'kerstmarkten',title:'3. Christmas markets around Duras',steps:['Open the Christmas markets page from the homepage.','Results start with markets nearest Duras and continue outwards, up to 50 km. When distances are equal, the earlier date appears first.','Choose dates or a town to refine the selection. Distances remain measured from Duras, even when you filter by another town.','Use the carousel arrows to view another market. You can pause automatic rotation. Open a card for market details.','Share this selection shares the page with your chosen dates and town. Supported devices open their sharing menu; otherwise the link is copied.'],notes:['The carousel follows the same filters as the results. If a selection is empty, choose All dates or clear the town filter.'],links:[{href:'/marches-de-noel',label:'Explore Christmas markets →'}]},
 {id:'gemeentegids',title:'4. Shops and practical services',steps:['Choose Shopping or Practical in the shared search area, or Local information in the menu.','The guide retrieves the selected service for your town. Use a shortcut or choose a different service in the dropdown. Show information reloads the results.','Select All categories for the full local guide. Use the phone, email, website and map links to contact a provider or plan a route.'],notes:['Sections include shops, town halls, health services, parking, charging points and public transport. Emergency numbers is an information section, not a business list.','Opening hours and photographs are shown when sources provide them. Photo not yet available means no suitable confirmed image can be displayed; contact details remain available.','Check the actual town and distance. A missing listing does not prove a service does not exist. Parking entries do not confirm spaces currently available.'],links:[{href:'/#gemeenten',label:'Open the local guide →'}]},
 {id:'toevoegen',title:'5. Submit an event or business',steps:['Search first to check whether the listing already exists. You do not need a duplicate listing to edit information or advertise.','Open Add / manage a listing. Choose an event or activity, a permanent listing, or a shop or service in the local guide.','Enter the title or business name, category, town, address and description. Only dated events need start and optional end dates and times. Complete the requested website, booking and source links.','Optionally add a photograph you own or may publish: JPG, PNG or WebP, up to 5 MB. Selecting a file does not save it.','Choose a free listing or paid advertising. Check the preview and required fields, then save your submission.','Keep the personal management link displayed afterwards: copy it or save it as a file. Provide the requested private email address for the link. Your submission awaits review.'],notes:['Free listing means no advertising fee. This event is free refers to admission for visitors. These are separate choices.','After approval, a confirmation email with the management link can be sent. Treat the link like a password and never post it on social media.'],links:[{href:'/mijn-vermelding',label:'Add / manage a listing →'},{href:'/evenement/nieuw',label:'Submit an event →'},{href:'/gemeentegids/aanmelden',label:'Submit a shop or service →'}]},
 {id:'wijzigen',title:'6. Edit information, photographs and management access',steps:['Open your personal management link, or paste the complete link into Open management link on the central management page.','Check the listing title at the top. Choose Edit details to change text, contact information, dates or a photograph.','Save changes and wait for confirmation. Owner changes are reviewed before publication. Existing advertising arrangements and payment history are retained.','Advertising and Payments belong to the same listing. Save your edits before switching sections. Open another listing allows you to use a different personal management link.'],notes:['For a local-guide business you can also edit the business email address and opening hours. Ask for help if its town or business category needs changing.','A saved owner photograph takes priority over a sourced image. Merely choosing a file does not update the published photograph.'],subsections:[{title:'No management link, or an error in a listing?',items:['Find the listing through Search & request and request management access or report a correction. Explain your connection to the organisation and the change required. The administrator verifies your authority before granting access.','Management link & help also offers recovery assistance. Compose recovery request opens a draft in your own email application; you must send it there yourself.','A correction request does not directly change public information. Recovery can invalidate older management links.']}],links:[{href:'/mijn-vermelding',label:'Manage my listing →'}]},
 {id:'advertenties',title:'7. Advertise in the calendar or local guide',intro:'Open your personal management link and choose Advertising. Preview cards show where your advertisement appears; a preview or payment summary is not an active advertisement.',subsections:[{title:'Events calendar',items:['Choose one or more formats: a highlighted listing, category advertisement or homepage advertisement. Your regular listing remains available.','Category advertisements appear in the selected event category; homepage advertisements appear on the homepage. Highlighted listings stand out within search results.']},{title:'Local guide',items:['A highlighted business stands out within its town and section. A section partner receives an additional card for that section; a town partner appears across the selected town’s sections.','Local-guide placements are separate from calendar placements. Advertising does not turn a guide business into an event.']}],steps:['Choose advertising formats, a start date and duration. Current prices and the combined total appear on the screen.','Check the previews and your contact and billing details. Private billing information is not displayed in the public listing.','Continue to Mollie using the indicated payment button. Placement follows content approval and payment confirmation, within the selected period and subject to availability.'],links:[{href:'/mijn-vermelding',label:'View my advertising options →'}]},
 {id:'betalingen',title:'8. Payments and invoices',steps:['Open your personal management link and select Payments. This shows the requests, periods, amounts and payment statuses for that listing.','Use Pay via Mollie or Resume payment via Mollie for an outstanding request. If unsure, check the payment status first to avoid paying twice.','Expired, cancelled or failed payments can be reopened when that option is available. Do not create a new listing for this.','Returning from Mollie alone does not confirm payment. Use Check payment status again if confirmation is still pending.'],notes:['Paid means payment is confirmed; the advertisement must also be approved and within its agreed period. Refunded means the payment has been returned.','Invoices are separate from the payment overview. When the administrator issues an invoice, it receives a sequential number and is emailed as a PDF to the billing email address. The personal payment overview currently has no invoice download button.','Missing invoice? Check spam and email info@cotededuras.com with your listing name and request reference.'],links:[{href:'/mijn-vermelding?onderdeel=betalingen',label:'Open my payments →'}]},
 {id:'hulp',title:'9. Sharing, language and help',notes:['External websites open in another tab. Availability and bookings are handled by the provider.','Use the social links at the bottom to follow Côte de Duras and share the website. Never share your personal management link publicly.','Statistics preferences at the bottom lets you change your choice about usage measurement.','For a larger view on a phone or tablet, open the website in Safari, Chrome or another regular browser.','For help, email info@cotededuras.com with the listing title, relevant page and request reference where applicable.'],links:[{href:'/contact',label:'Contact details →'},{href:'mailto:info@cotededuras.com',label:'Email Côte de Duras →'}]},
 {id:'voor-beheerders',title:'10. Administrators: content and access requests',intro:'Administrator sign-in is at the bottom of the website. This is separate from a personal link for managing one listing.',subsections:[{title:'Events and imports',items:['Open Awaiting review for manual submissions or All events for the complete administrative list. Search by name or filter by category.','Edit opens details and photographs. Review changes and save. Approve publishes a checked submission. Content approval does not confirm payment.','Refresh reloads saved data. Import buttons retrieve source information for a preview. Check titles, dates, photographs and categories before saving.','New imports from configured sources may be approved automatically. Manual submissions and owner changes are reviewed separately. Read the result message if a batch is only partly successful.','Social post preview uses the link and text of a specific post. It does not automatically scan private groups.']},{title:'Removing listings and managing businesses',items:['Delete archives a listing after confirmation, removing it from public and active lists. Linked requests and invoices are retained. No refund is made by this action.','Use Local guide · Manage businesses for business submissions, contact details, opening hours and photographs. Review new submissions and check their public display after saving.','Administrative totals may differ from visitor totals because of pending submissions, expired events and visitor search filters.']},{title:'Access requests and email',items:['Verify management authority through independently obtained official contact information. Record the checks and decision, and confirm the recipient address for the management link.','Resolving a correction request does not automatically update its content. Edit the relevant record in the appropriate administrative list.','Under the Strato mail connection, check connection, sending settings, schedules and queued messages. Mail-server acceptance is not proof of delivery or reading.','Requests and management links have a separate retry action from invoices. Read current status messages before retrying.','For automatic imports and daily updates, check the configured schedule and summary. An unavailable source may be reported as requiring attention.']}]},
 {id:'facturen-beheer',title:'11. Administrators: invoices and payments',steps:['Open Invoices & advertising requests, then the invoice overview. Check each genuine request for name, period, amount and billing information.','Check the VAT treatment, business information and any applicable exemption wording in Invoice settings. Save and verify confirmation.','Issue and send invoice assigns the next invoice number and queues the PDF email. A Mollie payment does not automatically create this invoice.','Check sending status. Retry emails processes pending or failed invoice messages without creating new invoices or invoice numbers.','Remove test request is available only for registered test requests. Adding TEST to a title is not sufficient. Issued invoices and their numbering are retained.'],notes:['Total invoiced covers issued, non-cancelled invoices excluding test invoices. Invoice status and Mollie payment status are different. Private billing details are visible only in administration.']},
 {id:'rapportages-beheer',title:'12. Administrators: visitors and marketing',steps:['Open Visitors & advertising reach and select 7, 30, 90 or 365 days. Refresh if necessary.','Use Marketing & acquisition for channels, campaigns and landing pages. Other tabs cover overview, days and months, categories, towns, search filters and advertisers.','Compare visitors and visits with opened listings and outbound clicks. Use identifiable campaign links to distinguish campaigns.','Save the report using Excel Save as… or CSV Save as…. View full report also displays the figures inside the administration area.'],notes:['Figures cover measured usage with consent. A visitor is a browser identifier, not a guaranteed unique person. Administrators are excluded.','Categories can overlap. A booking click is not a confirmed reservation, and these statistics do not count everyone who uses the site.']}
 ]},
 fr:{title:'Guide d’utilisation de Côte de Duras',description:'Rechercher des sorties et des services, découvrir les marchés de Noël, gérer une annonce, faire de la publicité et suivre les paiements.',kicker:'Aide aux visiteurs, aux professionnels et aux administrateurs',intro:'Côte de Duras réunit les événements et les adresses locales. Vous pouvez chercher sans compte, préparer une sortie et trouver des services dans la même commune.',updated:'Mis à jour le 16 novembre 2026',language:'Choisissez Nederlands, English ou Français en haut de la page. Une nouvelle visite commence en français ; la langue choisie reste active pendant votre navigation. Les noms, adresses et coordonnées ne sont pas traduits.',contents:'Que souhaitez-vous faire ?',home:'← Retour à l’accueil',discover:'Ouvrir la recherche →',top:'↑ Retour au sommaire',sections:[
 {id:'zoeken',title:'1. Commencer par Découvrez Duras et ses environs',steps:['Choisissez la commune à partir de laquelle vous souhaitez chercher.','Sélectionnez Que faire ? pour les événements, ou Que trouver à proximité ? pour les adresses et les services locaux.','Passez de Tout à Événements, Manger & boire, Commerces ou Pratique. La commune choisie reste sélectionnée.','Tout affiche l’agenda et le guide local. Dans Manger & boire, choisissez les restaurants ou les cafés. Commerces et Pratique proposent des raccourcis vers différentes rubriques.'],notes:['Le rayon de l’agenda concerne ses résultats. Le guide local applique une distance adaptée à chaque service ; une adresse peut se trouver hors de la commune choisie.'],links:[{href:'/#local-discovery',label:'Découvrir les environs →'}]},
 {id:'agenda',title:'2. Rechercher des événements et choisir des dates',steps:['Choisissez Événements et un rayon de 10, 25 ou 50 km. La recherche commence à 10 km.','Utilisez Aujourd’hui, Cette semaine ou Ce week-end. La semaine va du lundi au dimanche ; le week-end correspond au samedi et au dimanche. Le dimanche, le week-end en cours reste sélectionné. Les dates suivent l’heure locale française.','Une seule date recherche cette journée. Deux dates définissent une période, premier et dernier jours inclus. Les événements sur plusieurs jours sont retenus s’ils chevauchent cette période.','Toutes les dates ou Effacer les dates retire le filtre de dates. Sans ce filtre, les adresses permanentes sont également affichées ; avec des dates, seuls les événements datés apparaissent.','Affinez par type d’activité ou par accès gratuit. Afficher plus d’activités permet de consulter des résultats supplémentaires.'],notes:['Utiliser ma position demande l’autorisation du navigateur. Si la position est hors du secteur ou inutilisable, le site peut chercher autour de la commune choisie et vous en informe.','Ouvrez une annonce par sa photo, son titre ou le bouton de détail. Vérifiez la date, le lieu et le tarif. Les liens de réservation et de l’organisateur ouvrent le site du prestataire ; un clic ne constitue pas une réservation.','Profitez de votre journée permet de passer des détails d’un événement aux restaurants, commerces ou services de la même commune, lorsque celle-ci peut être identifiée.','Aucun résultat adapté ? Élargissez le rayon, effacez les dates, choisissez tous les types ou désactivez le filtre gratuit. Vérifiez les informations auprès de l’organisateur avant de partir.'],links:[{href:'/#agenda',label:'Ouvrir l’agenda →'}]},
 {id:'kerstmarkten',title:'3. Les marchés de Noël autour de Duras',steps:['Ouvrez la page des marchés de Noël depuis le bloc de la page d’accueil.','Les résultats commencent par les marchés les plus proches de Duras, puis s’éloignent jusqu’à 50 km. À distance égale, la date la plus proche apparaît en premier.','Choisissez une journée, une période ou une commune pour affiner la sélection. Les distances restent calculées depuis Duras, même si vous filtrez sur une autre commune.','Utilisez les flèches du carrousel pour voir un autre marché. Vous pouvez mettre la rotation automatique en pause. Ouvrez une carte pour consulter les détails.','Partager cette sélection partage la page avec les dates et la commune choisies. Selon l’appareil, le menu de partage s’ouvre ou le lien est copié.'],notes:['Le carrousel suit les mêmes filtres que les résultats. Si la sélection est vide, choisissez Toutes les dates ou retirez le filtre de commune.'],links:[{href:'/marches-de-noel',label:'Découvrir les marchés de Noël →'}]},
 {id:'gemeentegids',title:'4. Commerces et informations pratiques',steps:['Choisissez Commerces ou Pratique dans la recherche commune, ou Informations locales dans le menu.','Le guide recherche la rubrique sélectionnée pour votre commune. Utilisez un raccourci ou choisissez un service dans la liste. Afficher les informations permet de relancer la recherche.','Choisissez Toutes les catégories — guide local complet pour une vue d’ensemble. Utilisez les liens de téléphone, de courriel, de site web et de carte pour contacter un prestataire ou préparer un trajet.'],notes:['Les rubriques comprennent notamment les commerces, mairies, services de santé, stationnements, bornes de recharge et transports en commun. Numéros d’urgence est une rubrique d’information, pas une liste d’entreprises.','Les horaires et photos sont affichés lorsqu’une source les fournit. Photo non encore disponible signifie qu’aucune image adaptée et confirmée ne peut être affichée ; les coordonnées restent utilisables.','Vérifiez la commune et la distance réelles. Une absence de résultat ne prouve pas qu’un service n’existe pas. Les fiches de stationnement ne confirment pas le nombre de places actuellement libres.'],links:[{href:'/#gemeenten',label:'Ouvrir le guide local →'}]},
 {id:'toevoegen',title:'5. Proposer un événement ou une entreprise',steps:['Vérifiez d’abord que l’annonce n’existe pas déjà. Il n’est pas nécessaire de créer un doublon pour la modifier ou faire de la publicité.','Ouvrez Ajouter / gérer une annonce. Choisissez un événement ou une activité, une adresse permanente, ou un commerce ou service du guide local.','Renseignez le titre ou le nom de l’entreprise, la catégorie, la commune, l’adresse et la description. Seuls les événements datés nécessitent une date et une heure de début et éventuellement de fin. Complétez les liens demandés : site web, réservation et source.','Ajoutez si vous le souhaitez une photo que vous possédez ou êtes autorisé à publier : JPG, PNG ou WebP, 5 Mo maximum. Choisir un fichier ne l’enregistre pas.','Choisissez une annonce gratuite ou une formule publicitaire payante. Vérifiez l’aperçu et les champs obligatoires, puis enregistrez la proposition.','Conservez le lien personnel de gestion affiché ensuite : copiez-le ou enregistrez-le dans un fichier. Indiquez aussi l’adresse privée demandée pour recevoir ce lien. La proposition est soumise à vérification.'],notes:['Annonce gratuite signifie sans frais de publicité. Cet événement est gratuit concerne le droit d’entrée des visiteurs. Ce sont deux choix distincts.','Après validation, un courriel de confirmation contenant le lien de gestion peut être envoyé. Gardez ce lien comme un mot de passe et ne le publiez jamais sur les réseaux sociaux.'],links:[{href:'/mijn-vermelding',label:'Ajouter / gérer une annonce →'},{href:'/evenement/nieuw',label:'Proposer un événement →'},{href:'/gemeentegids/aanmelden',label:'Inscrire un commerce ou un service →'}]},
 {id:'wijzigen',title:'6. Modifier les informations, la photo et l’accès',steps:['Ouvrez votre lien personnel ou collez-le en entier dans Ouvrir le lien de gestion, depuis la page centrale de gestion des annonces.','Vérifiez le titre de l’annonce en haut de la page. Choisissez Modifier les informations pour changer les textes, coordonnées, dates ou photo.','Enregistrez et attendez la confirmation. Les modifications du propriétaire sont vérifiées avant publication. Les accords publicitaires et l’historique des paiements sont conservés.','Les rubriques Publicité et Paiements concernent la même annonce. Enregistrez avant de changer de rubrique. Ouvrir une autre annonce permet d’utiliser un autre lien personnel.'],notes:['Pour une entreprise du guide local, vous pouvez aussi modifier le courriel professionnel et les horaires. Demandez de l’aide pour changer la commune d’implantation ou la rubrique.','Une photo enregistrée par le propriétaire est prioritaire sur une image provenant d’une source publique. Le simple choix d’un fichier ne modifie pas la photo publiée.'],subsections:[{title:'Sans lien de gestion ou en cas d’erreur',items:['Recherchez la fiche dans Rechercher & demander, puis demandez la gestion ou signalez une correction. Précisez votre lien avec l’organisation et le changement souhaité. L’administrateur vérifie votre autorisation avant de donner accès.','Lien de gestion & aide permet également de demander une récupération. Préparer le courriel de récupération ouvre un brouillon dans votre messagerie ; vous devez l’envoyer vous-même.','Une demande de correction ne modifie pas immédiatement les informations publiques. Une récupération peut rendre les anciens liens invalides.']}],links:[{href:'/mijn-vermelding',label:'Gérer mon annonce →'}]},
 {id:'advertenties',title:'7. Faire de la publicité dans l’agenda ou le guide local',intro:'Ouvrez votre lien personnel et choisissez Publicité. Les cartes d’aperçu indiquent l’emplacement de l’annonce ; un aperçu ou un récapitulatif de paiement n’est pas une publicité active.',subsections:[{title:'Agenda des événements',items:['Choisissez une ou plusieurs formules : annonce encadrée, publicité de catégorie ou publicité en page d’accueil. Votre annonce habituelle est conservée.','La publicité de catégorie apparaît dans la catégorie choisie ; celle de la page d’accueil apparaît à l’accueil. L’annonce encadrée se distingue parmi les résultats.']},{title:'Guide local',items:['Une annonce encadrée se distingue dans sa commune et sa rubrique. Un partenaire de rubrique dispose d’une carte supplémentaire dans cette rubrique ; un partenaire de commune apparaît dans les rubriques de la commune choisie.','Les emplacements du guide local sont distincts de ceux de l’agenda. Faire de la publicité ne transforme pas une entreprise du guide en événement.']}],steps:['Choisissez les formules, la date de début et la durée. Les tarifs en vigueur et le total sont affichés à l’écran.','Vérifiez les aperçus et vos coordonnées de contact et de facturation. Les informations privées de facturation ne figurent pas sur l’annonce publique.','Continuez vers Mollie avec le bouton indiqué. La diffusion intervient après validation du contenu et confirmation du paiement, pendant la période choisie et selon les disponibilités.'],links:[{href:'/mijn-vermelding',label:'Voir mes possibilités publicitaires →'}]},
 {id:'betalingen',title:'8. Paiements et factures',steps:['Ouvrez votre lien personnel et choisissez Paiements. Vous y trouvez les demandes, périodes, montants et statuts associés à cette annonce.','Utilisez Payer via Mollie ou Reprendre le paiement via Mollie pour une demande en attente. En cas de doute, contrôlez d’abord le statut pour éviter un double paiement.','Un paiement expiré, annulé ou échoué peut être rouvert lorsque cette possibilité est proposée. Ne créez pas une nouvelle annonce pour cela.','Le seul retour de Mollie ne confirme pas le paiement. Utilisez Vérifier à nouveau le paiement si la confirmation manque encore.'],notes:['Payé signifie que le paiement est confirmé ; la publicité doit également être validée et dans sa période de diffusion. Remboursé signifie que le montant a été restitué.','La facture est distincte de l’historique des paiements. Lorsque l’administrateur l’établit, elle reçoit un numéro séquentiel et est envoyée en PDF au courriel de facturation. L’espace personnel ne propose actuellement pas de bouton de téléchargement des factures.','Facture manquante ? Vérifiez les courriels indésirables et écrivez à info@cotededuras.com en précisant l’annonce et la référence de la demande.'],links:[{href:'/mijn-vermelding?onderdeel=betalingen',label:'Ouvrir mes paiements →'}]},
 {id:'hulp',title:'9. Partager, choisir la langue et obtenir de l’aide',notes:['Les sites externes s’ouvrent dans un autre onglet. Les disponibilités et réservations sont gérées par le prestataire.','Les liens sociaux en bas de page permettent de suivre Côte de Duras et de partager le site. Ne partagez jamais publiquement votre lien personnel de gestion.','Préférences statistiques, en bas de page, permet de modifier votre choix concernant la mesure de fréquentation.','Pour un affichage plus grand sur téléphone ou tablette, ouvrez le site dans Safari, Chrome ou un autre navigateur habituel.','Pour obtenir de l’aide, écrivez à info@cotededuras.com avec le titre de l’annonce, la page concernée et, si nécessaire, la référence de la demande.'],links:[{href:'/contact',label:'Coordonnées →'},{href:'mailto:info@cotededuras.com',label:'Écrire à Côte de Duras →'}]},
 {id:'voor-beheerders',title:'10. Administrateurs : contenu et demandes d’accès',intro:'La connexion administrateur se trouve en bas du site. Elle est distincte du lien personnel permettant de gérer une seule annonce.',subsections:[{title:'Événements et imports',items:['Ouvrez En attente de vérification pour les propositions manuelles ou Tous les événements pour la liste complète. Recherchez par nom ou filtrez par catégorie.','Modifier ouvre les informations et la photo. Vérifiez et enregistrez. Approuver publie une proposition contrôlée. La validation du contenu ne confirme pas le paiement.','Actualiser recharge les données enregistrées. Les boutons d’import récupèrent les sources pour un aperçu. Contrôlez les titres, dates, photos et catégories avant l’enregistrement.','Les nouveaux imports des sources configurées peuvent être approuvés automatiquement. Les propositions manuelles et modifications des propriétaires sont contrôlées séparément. Lisez le résultat si un lot est partiellement traité.','Aperçu de publication sociale utilise le lien et le texte d’une publication précise. Le formulaire n’analyse pas automatiquement les groupes privés.']},{title:'Retrait d’annonces et gestion des entreprises',items:['Supprimer archive l’annonce après confirmation et la retire des listes publiques et actives. Les demandes et factures liées restent conservées. Cette action ne déclenche aucun remboursement.','Guide local · Gérer les entreprises permet de contrôler les inscriptions, coordonnées, horaires et photos. Examinez les nouvelles demandes et vérifiez l’affichage public après enregistrement.','Les totaux de gestion peuvent différer des totaux visiteurs en raison des propositions en attente, événements passés et filtres de recherche.']},{title:'Demandes d’accès et courriels',items:['Vérifiez les droits du demandeur à partir de coordonnées officielles obtenues indépendamment. Consignez les vérifications et la décision, puis contrôlez l’adresse destinataire du lien.','Clôturer une demande de correction ne met pas automatiquement le contenu à jour. Modifiez d’abord la fiche dans la liste de gestion appropriée.','Dans la connexion mail Strato, vérifiez la connexion, l’envoi, la planification et les files d’attente. L’acceptation par le serveur ne prouve pas la réception ni la lecture.','Les demandes et liens de gestion disposent d’une action de nouvelle tentative distincte de celle des factures. Consultez les statuts avant de relancer.','Pour les imports automatiques et mises à jour quotidiennes, vérifiez la planification et le récapitulatif. Une source indisponible peut être signalée comme point à contrôler.']}]},
 {id:'facturen-beheer',title:'11. Administrateurs : factures et paiements',steps:['Ouvrez Factures & demandes publicitaires, puis le récapitulatif des factures. Contrôlez chaque demande réelle : nom, période, montant et coordonnées de facturation.','Vérifiez le régime de TVA, les informations de l’entreprise et l’éventuelle mention d’exonération dans les paramètres de facturation. Enregistrez et contrôlez la confirmation.','Établir et envoyer la facture attribue le numéro suivant et prépare le courriel avec le PDF. Un paiement Mollie ne crée pas automatiquement cette facture.','Contrôlez l’envoi. Réessayer les courriels traite les messages de facturation en attente ou échoués sans créer de nouvelles factures ni de nouveaux numéros.','Retirer une demande de test est réservé aux demandes enregistrées comme tests. Ajouter TEST dans un titre ne suffit pas. Les factures émises et leur numérotation sont conservées.'],notes:['Le total facturé concerne les factures émises et non annulées, hors tests. Le statut d’une facture est distinct du statut Mollie. Les données privées de facturation restent dans l’administration.']},
 {id:'rapportages-beheer',title:'12. Administrateurs : fréquentation et marketing',steps:['Ouvrez Visiteurs & portée publicitaire et choisissez 7, 30, 90 ou 365 jours. Actualisez si nécessaire.','Marketing & provenance présente les canaux, campagnes et pages d’arrivée. Les autres onglets couvrent la vue d’ensemble, jours et mois, catégories, communes, filtres et annonceurs.','Comparez visiteurs et visites aux ouvertures de fiches et aux clics sortants. Utilisez des liens de campagne identifiables pour distinguer les actions marketing.','Enregistrez le rapport avec Excel Enregistrer sous… ou CSV Enregistrer sous…. Afficher le rapport complet permet aussi de lire les données dans l’administration.'],notes:['Les chiffres concernent l’usage mesuré avec consentement. Un visiteur correspond à un identifiant de navigateur, pas à une personne unique garantie. Les administrateurs sont exclus.','Les catégories peuvent se chevaucher. Un clic de réservation n’est pas une réservation confirmée et les statistiques ne comptabilisent pas tous les utilisateurs du site.']}
 ]}
};
